Title: Proposal: Prevent unused argument warning in HAL_EXTI_GetPending and HAL_EXTI_ClearPending

Body:
**Describe the set-up**
 * Board: NUCLEO-F767ZI
 * IDE/Compiler: SEGGER Embedded Studio 8.24 / SEGGER Compiler

**Additional context**
In the file stm32f7xx_hal_exti.c, I have added the following patch in the functions HAL_EXTI_GetPending and HAL_EXTI_ClearPending:

c
  /* Prevent unused argument(s) compilation warning */
  UNUSED(Edge);

Details of the functions:

c
/**
  * @brief  Get interrupt pending bit of a dedicated line.
  * @param  hexti Exti handle.
  * @param  Edge Specify which pending edge as to be checked.
  *         This parameter can be one of the following values:
  *           @arg @ref EXTI_TRIGGER_RISING_FALLING
  *         This parameter is kept for compatibility with other series.
  * @retval 1 if interrupt is pending else 0.
  */
uint32_t HAL_EXTI_GetPending(EXTI_HandleTypeDef *hexti, uint32_t Edge)
{
  uint32_t regval;
  uint32_t linepos;
  uint32_t maskline;

/* Prevent unused argument(s) compilation warning */
  UNUSED(Edge);

/* Check parameters */
  assert_param(IS_EXTI_LINE(hexti->Line));
  assert_param(IS_EXTI_CONFIG_LINE(hexti->Line));
  assert_param(IS_EXTI_PENDING_EDGE(Edge));

/* Compute line mask */
  linepos = (hexti->Line & EXTI_PIN_MASK);
  maskline = (1uL << linepos);

/* return 1 if bit is set else 0 */
  regval = ((EXTI->PR & maskline) >> linepos);
  return regval;
}

/**
  * @brief  Clear interrupt pending bit of a dedicated line.
  * @param  hexti Exti handle.
  * @param  Edge Specify which pending edge as to be clear.
  *         This parameter can be one of the following values:
  *           @arg @ref EXTI_TRIGGER_RISING_FALLING
  *         This parameter is kept for compatibility with other series.
  * @retval None.
  */
void HAL_EXTI_ClearPending(EXTI_HandleTypeDef *hexti, uint32_t Edge)
{
  uint32_t maskline;

/* Prevent unused argument(s) compilation warning */
  UNUSED(Edge);

/* Check parameters */
  assert_param(IS_EXTI_LINE(hexti->Line));
  assert_param(IS_EXTI_CONFIG_LINE(hexti->Line));
  assert_param(IS_EXTI_PENDING_EDGE(Edge));

/* Compute line mask */
  maskline = (1uL << (hexti->Line & EXTI_PIN_MASK));

/* Clear Pending bit */
  EXTI->PR =  maskline;
}

/* Mask containing trigger source masks for each of possible                  */
/* trigger edge selection duplicated with shifts [0; 4; 8; 12]                */
/* corresponding to {SW start; ext trigger; ext trigger; ext trigger}.        */
#define ADC_REG_TRIG_SOURCE_MASK            (((LL_ADC_REG_TRIG_SOFTWARE & ADC_CR2_EXTSEL) >> (4U * 0U)) | \
                                             ((ADC_CR2_EXTSEL)                            >> (4U * 1U)) | \
                                             ((ADC_CR2_EXTSEL)                            >> (4U * 2U)) | \
                                             ((ADC_CR2_EXTSEL)                            >> (4U * 3U)))

I don't really understand why there is a need for the extra logic in the Get version of the function. Looking at the Set version, it simply writes the TriggerSource value to the ADC_CR2_EXTSEL register bits of the ADC peripheral. Why does the Get care about ADC_CR2_EXTSEL, and apply shifts for that? Why does GetTriggerSource() not just get what SetTriggerSource() set?

Am I doing something wrong, or is there indeed an issue with the current implementation?

ISSUE1:
NOR_WRITE casts addresses to a 16-bit pointer.  So when 'writing' to a 8-bit Flash, it is writing 2 bytes instead of just 1.
ISSUE2:
hnor->CommandSet = *(__IO uint16_t *) NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_ADDRESS_COMMAND_SET);
This line also has an explicit 16-bit cast.  WHen working with 8-bit flash, this should be an 8-bit cast - THe  16-bit cast is causing a mis-aligned memory access when reading the command set (the address is 0x13... which is odd).
Odd-alligned memory access is prohibited for 16-bit pointers.
ISSUE3:
~this section~
C
    /* Get the value of the command set */
    if (uwNORMemoryDataWidth == NOR_MEMORY_8B)
    {
      NOR_WRITE(NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_CMD_ADDRESS_FIRST_CFI_BYTE),
                NOR_CMD_DATA_CFI);
    }
    else
    {
      NOR_WRITE(NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_CMD_ADDRESS_FIRST_CFI), NOR_CMD_DATA_CFI);
    }

[StephenPTxEng - 2025-04-14T18:46:33Z]
TL;DR:
Original Generated Code for the end of the HAL_NOR_Init():
C
//...
else
  {
    /* Get the value of the command set */
    if (uwNORMemoryDataWidth == NOR_MEMORY_8B)
    {
      NOR_WRITE(NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_CMD_ADDRESS_FIRST_CFI_BYTE),
                NOR_CMD_DATA_CFI);
    }
    else
    {
      NOR_WRITE(NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_CMD_ADDRESS_FIRST_CFI), NOR_CMD_DATA_CFI);
    }

hnor->CommandSet = *(__IO uint16_t *) NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_ADDRESS_COMMAND_SET);

status = HAL_NOR_ReturnToReadMode(hnor);
  }
//...

My suggested change:
C
//...
else
  {
    /* Get the value of the command set */
    NOR_WRITE_8b(NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_CMD_ADDRESS_FIRST_CFI), 
                NOR_CMD_DATA_CFI);
    hnor->CommandSet = *(__IO uint8_t *)NOR_ADDR_SHIFT(deviceaddress, uwNORMemoryDataWidth, NOR_ADDRESS_COMMAND_SET);

status = HAL_NOR_ReturnToReadMode(hnor);
  }
//...
/**
  * @brief  NOR memory write 8-bit data to specified address.
  * @param  __ADDRESS__ NOR memory address
  * @param  __DATA__ Data to write
  * @retval None
  */
#define NOR_WRITE_8b(__ADDRESS__, __DATA__)   do{                                                             \
                                               (*(__IO uint8_t *)((uint32_t)(__ADDRESS__)) = (__DATA__)); \
                                               __DSB();                                                    \
                                             } while(0)

### **_And this needs to be done everywhere in the HAL_NOR file._**
To support different data types, HAL_NOR_Read() and HAL_NOR_Program() must have their signatures changed to the following

HAL_StatusTypeDef HAL_NOR_Read(NOR_HandleTypeDef *hnor, uint32_t *pAddress, uint16_t *pData); 
becomes
HAL_StatusTypeDef HAL_NOR_Read(NOR_HandleTypeDef *hnor, uint8_t *pAddress, void *pData);

and
HAL_StatusTypeDef HAL_NOR_Program(NOR_HandleTypeDef *hnor, uint32_t *pAddress, uint16_t *pData);
becomes
HAL_StatusTypeDef HAL_NOR_Program(NOR_HandleTypeDef *hnor, uint8_t *pAddress, uint32_t Data);

